<template><div class="store-settings-page"><div class="page-title"><div><p class="eyebrow">STORE PROFILE</p><h1>店面管理</h1><p>当前店面：{{currentStore?.name||'加载中'}}。设置只会影响这个店面。</p></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form :model="form" label-position="top" class="dish-form"><el-form-item label="店铺名称" required><el-input v-model="form.name" maxlength="80"/></el-form-item><el-form-item label="欢迎语"><el-input v-model="form.tagline" maxlength="120"/></el-form-item><el-form-item label="店铺公告"><el-input v-model="form.announcement" maxlength="240" type="textarea" :rows="3"/></el-form-item><el-form-item label="营业状态"><div class="open-setting"><el-switch v-model="form.isOpen" active-text="营业中" inactive-text="暂停接单"/><p>暂停营业时，客人无法提交新订单。</p></div></el-form-item><el-form-item label="地址"><el-input v-model="form.address" maxlength="160"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.phone" maxlength="40"/></el-form-item><el-form-item label="客人点餐链接"><el-input :model-value="guestUrl" readonly><template #append><el-button @click="copyLink">复制</el-button></template></el-input></el-form-item><div class="form-actions"><el-button type="primary" :loading="saving" @click="save">保存店面设置</el-button><el-button v-if="stores.length>1" type="danger" plain @click="removeStore">删除当前店铺</el-button></div></el-form></div></template>
<script setup lang="ts">import {reactive,ref,computed,onMounted,watch} from 'vue';import {useRouter} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {api,type Store} from '../api';import {stores,activeStoreId,loadStores} from '../storeContext';const router=useRouter(),error=ref(''),saving=ref(false),currentStore=computed(()=>stores.value.find(s=>s.id===activeStoreId.value)),guestUrl=computed(()=>`${window.location.origin}/guest?storeId=${activeStoreId.value}`),form=reactive<Store>({id:'',name:'',tagline:'',announcement:'',isOpen:true,address:'',phone:''});async function load(){error.value='';try{const s:Store=(await api.get('/store',{params:{storeId:activeStoreId.value}})).data.data;Object.assign(form,s)}catch(e:any){error.value=e.message}}async function save(){if(!form.name.trim()){error.value='请填写店铺名称';return}error.value='';saving.value=true;try{Object.assign(form,(await api.put('/store',{...form,id:activeStoreId.value},{params:{storeId:activeStoreId.value}})).data.data);ElMessage.success('店面设置已保存');await loadStores()}catch(e:any){error.value=e.message}finally{saving.value=false}}async function removeStore(){const id=activeStoreId.value;try{await ElMessageBox.confirm(`确定删除「${currentStore.value?.name}」？该店铺的菜单也会删除；有历史订单时系统会阻止删除。`,'删除店铺',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'});await api.delete(`/stores/${id}`);await loadStores();ElMessage.success('店铺已删除');await router.push('/admin')}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'删除失败')}}async function copyLink(){await navigator.clipboard.writeText(guestUrl.value);ElMessage.success('点餐链接已复制')}onMounted(async()=>{await loadStores();await load()});watch(activeStoreId,load);</script>
